; Generated by EXX.

; Consume the pending bit, encode the channel and set the ready bit.
update_channel:
    bit 0, (ix + PACKET.status)
    ret z
    res 0, (ix + PACKET.status)
    and 7
    sla a
    or 128
    ld (ix + PACKET.flags), a
    set 1, (ix + PACKET.status)
    ret

; Shift DE right as a single signed word and return the bit shifted out of E.
halve_signed:
    sra d
    rr e
    ret

; Add DE and the incoming carry to HL.
accumulate:
    adc hl, de
    ret
